  {
    accessorKey: 'status',
    header: 'Статус',
    size: 160,
    enableGrouping: true,
    cell: (info) => {
      const value = info.getValue<string>();
      return statusLabels[value] ?? value;
    },
  },
];

export function OrdersTable() {
  const [data] = React.useState<Order[]>(mockOrders);
  const [rowSelection, setRowSelection] = React.useState<RowSelectionState>({});
